let tasks = initialTasks.map(t => ({ ...t }));
let state = { page: "overview", scenario: "normal", role: "operator", type: "all", query: "", taskFilter: "all", search: "", searchStatus: "all", searchPage: 0, nextTask: 5, draft: 1 };
const $ = id => document.getElementById(id);
const esc = value => String(value ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const entityFor = id => entities.find(e => e.id === id);
function badge(text, color = "") { return `<span class="badge ${color}"><span class="dot"></span>${esc(text)}</span>`; }
function taskBadge(t) { return badge(statusNames[t.status], t.status === "EXECUTING" ? "blue" : t.status === "SUCCEEDED" ? "" : terminals.has(t.status) ? "gray" : "amber"); }
function writable(e) { return !!e.executor && e.fresh && e.status !== "忙碌" && state.scenario !== "disconnected"; }
