    `<div class="kpis">${[["当前示例实体", "6", "个", "六类来源，统一状态视图", "◇"], ["具备巡检能力", "4", "个", "以注册绑定与最新状态为准", "✓"], ["进行中的任务", active, "项", "创建到终态，全程可追踪", "⇄"], ["需关注的快照", "1", "个", "车辆数据已过期，需确认", "◷"]].map(k => `<div class="kpi"><div class="kpi-label">${k[0]}</div><div class="kpi-value">${k[1]}<small>${k[2]}</small></div><div class="kpi-hint">${k[3]}</div><span class="kpi-icon" aria-hidden="true">${k[4]}</span></div>`).join("")}</div>` +
    `<div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>园区状态分布</h2><p>空间示意 · 点击标记查看实体</p></div><span class="badge gray">示意园区</span></div><div class="park"><div class="park-lake"></div><div class="park-legend"><span>● 执行实体</span><span>● 状态实体</span></div><span class="north">↑ N</span><div class="building a">A 区 · 办公</div><div class="building b">B 区 · 设备</div><div class="building c">中央广场</div><div class="building d">C 区 · 充电</div>${entities.map(e => `<button class="marker ${!e.executor ? "state-only" : ""} ${!e.fresh ? "stale" : ""}" style="left:${e.position[0]}%;top:${e.position[1]}%" data-entity="${e.id}" aria-label="查看${e.name}${e.fresh ? "" : "，快照已过期"}" title="${e.name}">${typeIcons[e.type]}</button>`).join("")}<div class="park-caption">模拟布局 · 非地图定位或路径规划</div></div></section><section class="panel"><div class="panel-head"><div><h2>需要关注</h2><p>按当前模拟状态整理</p></div><span class="badge gray">3</span></div><div class="activity-list"><div class="activity"><span class="activity-symbol amber">◷</span><div><p>运输车状态待更新</p><small>最后上报 72 秒前<br>创建巡检前需重新确认</small><button class="text-button" data-entity="vehicle-001">查看实体 →</button></div></div><div class="activity"><span class="activity-symbol">⇄</span><div><p>东区任务待处理</p><small>最新下发尝试进入死信<br>业务任务仍为待分发</small><button class="text-button" data-task="demo-task-002">查看任务 →</button></div></div><div class="activity"><span class="activity-symbol teal">✓</span><div><p>人员巡检已完成</p><small>已保留模拟结果与状态记录</small><button class="text-button" data-task="demo-task-003">查看结果 →</button></div></div></div></section></div>` + entityTable();
