function openCancel(id) { const t = tasks.find(x => x.id === id); if (!t || terminals.has(t.status) || t.cancel) return; openDialog("请求取消任务", `${t.name} / ${id}`, `<div class="notice warning">这里只提交取消意图。收到执行器确认或权威终态之前，任务可能继续执行。</div><form id="cancel-form" data-id="${id}"><label class="field">取消原因<textarea name="reason" required placeholder="请说明取消原因（1–1024 UTF-8 字节）"></textarea></label><div id="form-error" class="form-error" role="alert"></div></form>`, `<button class="secondary" data-task="${id}">返回任务</button><button class="danger-button" form="cancel-form" type="submit">模拟提交取消意图</button>`); }
function openRetry(id) { if (state.role !== "admin") { toast("人工重试需要管理员身份。"); return; } openDialog("人工重试死信", `${id} · 仅模拟传输重试`, '<div class="notice warning">重试不会生成新业务任务。accepted=true 表示重试轮次已持久化，不表示已送达或执行成功。</div><form id="retry-form" data-id="' + id + '"><label class="field">干预原因<textarea name="reason" required placeholder="记录人工干预原因（1–1024 UTF-8 字节）"></textarea></label><div id="form-error" class="form-error" role="alert"></div></form>', '<button class="secondary" data-action="close">返回</button><button class="primary" form="retry-form" type="submit">模拟重试</button>'); }
function recover() { const clear = state.scenario === "empty"; state.scenario = "normal"; state.searchPage = 0; if (clear) { state.type = "all"; state.query = ""; state.search = ""; state.searchStatus = "all"; } $("scenario").value = "normal"; render(); toast("模拟视图已重新同步。"); }
document.addEventListener("click", event => {
  const el = event.target.closest("button, a"); if (!el || el.disabled) return;
  if (el.dataset.nav) navigate(el.dataset.nav);
  else if (el.classList.contains("brand")) { event.preventDefault(); navigate("overview"); }
  else if (el.dataset.entity) openEntity(el.dataset.entity);
  else if (el.dataset.task) openTask(el.dataset.task);
  else if (el.dataset.type) { state.type = el.dataset.type; render(); $("filter-" + state.type).focus(); }
  else if (el.dataset.taskFilter) { state.taskFilter = el.dataset.taskFilter; render(); $("taskfilter-" + state.taskFilter).focus(); }
  else if (el.dataset.createEntity) openCreate(el.dataset.createEntity);
  else if (el.dataset.cancelTask) openCancel(el.dataset.cancelTask);
  else if (el.dataset.retry) openRetry(el.dataset.retry);
  else if (el.dataset.action) {
    const a = el.dataset.action;
    if (a === "close") $("detail-dialog").close();
    if (a === "create") openCreate();
    if (a === "recover") recover();
    if (a === "refresh") toast("模拟刷新完成 · 未请求任何后端服务。");
    if (a === "search-next") { state.searchPage++; render(); }
    if (a === "search-reset") { state.searchPage = 0; render(); }
  }
});
document.addEventListener("submit", event => {
  event.preventDefault(); const form = event.target; const data = new FormData(form);
  if (form.id === "entity-filter") { state.query = String(data.get("query")); render(); $("entity-query").focus(); }
  if (form.id === "task-search") { state.search = String(data.get("keyword")); state.searchStatus = String(data.get("status")); state.searchPage = 0; render(); }
  if (form.id === "dispatch-query") { const t = tasks.find(x => x.id === String(data.get("taskId")).trim()); t ? openDispatch(t.id) : toast("该任务不在本地模拟数据中。"); }
  if (form.id === "create-form") {
    const e = entityFor(data.get("entity")), duration = Number(data.get("duration")), priority = Number(data.get("priority")), note = String(data.get("note")).trim();
    const deadline = Date.parse(String(data.get("deadline")) + ":00+08:00"), now = Date.parse("2026-09-12T14:32:10+08:00");
    if (!e || !writable(e) || !Number.isInteger(duration) || duration < 1 || duration > 60 || priority !== 5 || new TextEncoder().encode(note).length > 256 || !Number.isFinite(deadline) || deadline <= now || deadline > now + 86400000) { $("form-error").textContent = "请检查实体可用性、整数范围、备注字节长度与截止时间。"; return; }
    const id = `demo-task-${String(state.nextTask++).padStart(3, "0")}`;
    tasks.unshift({ id, name: note || `${typeNames[e.type]}巡检`, entity: e.id, status: "CREATED", cancel: false, version: 1, note, created: "14:32:10", duration, priority, deadline: String(data.get("deadline")) + " +08:00", delivery: "pending", attempt: 1 }); state.draft++;
    $("detail-dialog").close(); navigate("tasks"); toast("模拟任务已创建；未下发任何真实指令。"); openTask(id);
  }
  if (form.id === "cancel-form" || form.id === "retry-form") {
    const reason = String(data.get("reason")).trim(), bytes = new TextEncoder().encode(reason).length;
    if (bytes < 1 || bytes > 1024) { $("form-error").textContent = "原因需为 1–1024 UTF-8 字节。"; return; }
    const t = tasks.find(x => x.id === form.dataset.id); if (!t) return;
    if (form.id === "cancel-form") { if (terminals.has(t.status) || t.cancel) return; t.cancel = true; t.cancelReason = reason; t.version++; render(); openTask(t.id); toast("模拟取消意图已记录；任务状态尚未变为已取消。"); }
    else { if (state.role !== "admin" || terminals.has(t.status) || t.cancel || t.delivery !== "dlq") { $("form-error").textContent = "当前任务或身份不满足重试条件。"; return; } t.attempt++; t.delivery = "pending"; $("detail-dialog").close(); render(); toast("模拟重试轮次已记录；业务执行标识保持不变。"); }
  }
});
